INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Kundenorientierung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist Kundenorientierung in der IT immer abhängig von direkter persönlicher Interaktion?', 2, '[{"text": "Nein", "correct": true, "because": "Digitale Kanäle wie E-Mail oder Ticketsysteme sind ebenso effektiv"}, {"text": "Ja", "correct": false, "because": "Verschiedene Kommunikationswege sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Kundenorientierung die Zufriedenheit der Kunden erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf Kundenbedürfnisse verbessert die Erfahrung"}, {"text": "Nein", "correct": false, "because": "Kundenorientierung wirkt sich positiv aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen IT-Mitarbeiter technische Details immer vollständig an Kunden erklären, um kundenorientiert zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit und Verständlichkeit sind wichtiger als technische Tiefe"}, {"text": "Ja", "correct": false, "because": "Übermäßige Details können verwirren"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Missverständnisse in der Kommunikation die Kundenorientierung beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Unklarheiten führen zu Frustration"}, {"text": "Nein", "correct": false, "because": "Kommunikation ist zentral für Kundenorientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Kundenorientierung ohne Rücksicht auf Kundenfeedback effektiv?', 2, '[{"text": "Nein", "correct": true, "because": "Feedback ist essenziell für Anpassung"}, {"text": "Ja", "correct": false, "because": "Ohne Feedback fehlt Kundenbezug"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist für Kundenorientierung in der IT am wichtigsten?', 3, '[{"text": "Verständnis der Kundenbedürfnisse", "correct": true, "because": "Grundlage für maßgeschneiderte Lösungen"}, {"text": "Maximale technische Komplexität", "correct": false, "because": "Kunden wollen Einfachheit"}, {"text": "Schnellste Antwortzeit", "correct": false, "because": "Wichtig, aber nicht allein entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten zeigt Kundenorientierung in der Kommunikation?', 2, '[{"text": "Aktives Zuhören", "correct": true, "because": "Zeigt Interesse an Kundenanliegen"}, {"text": "Technischer Jargon", "correct": false, "because": "Kann Kunden verwirren"}, {"text": "Ignorieren von Rückfragen", "correct": false, "because": "Mindert Vertrauen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Kundenorientierung in der IT?', 2, '[{"text": "Erfüllung der Kundenanforderungen", "correct": true, "because": "Kundenzufriedenheit steht im Mittelpunkt"}, {"text": "Reduktion der Supportkosten", "correct": false, "because": "Nebenaspekt"}, {"text": "Vermeidung von Kundeninteraktion", "correct": false, "because": "Gegenteil ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann die Kundenorientierung in der Kommunikation mindern?', 3, '[{"text": "Mangelnde Empathie", "correct": true, "because": "Kunden fühlen sich nicht verstanden"}, {"text": "Schnelle Problemlösung", "correct": false, "because": "Positiv, kein Fehler"}, {"text": "Regelmäßige Updates", "correct": false, "because": "Fördert Vertrauen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool unterstützt die Kundenorientierung durch strukturierten Austausch?', 2, '[{"text": "CRM-System", "correct": true, "because": "Verwaltet Kundeninteraktionen"}, {"text": "Texteditor", "correct": false, "because": "Kein Kommunikationswerkzeug"}, {"text": "Netzwerkscanner", "correct": false, "because": "Technische Analyse, nicht Kundenbezug"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördern die Kundenorientierung in der Kommunikation?', 4, '[{"text": "Klarheit", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Empathie", "correct": true, "because": "Zeigt Verständnis"}, {"text": "Reaktionsschnelligkeit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Technische Überlegenheit", "correct": false, "because": "Nicht kundenrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verbessern die Kundenorientierung?', 3, '[{"text": "Regelmäßiges Feedback einholen", "correct": true, "because": "Passt Service an"}, {"text": "Proaktive Kommunikation", "correct": true, "because": "Informiert Kunden frühzeitig"}, {"text": "Anpassung an Kundenwünsche", "correct": true, "because": "Erhöht Zufriedenheit"}, {"text": "Ignorieren von Beschwerden", "correct": false, "because": "Mindert Vertrauen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Kundenorientierung beeinträchtigen?', 4, '[{"text": "Unklare Antworten", "correct": true, "because": "Verwirrt Kunden"}, {"text": "Langsame Reaktionen", "correct": true, "because": "Frustriert Kunden"}, {"text": "Fehlende Rückmeldung", "correct": true, "because": "Kunden fühlen sich ignoriert"}, {"text": "Schnelle Problemlösung", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kommunikationskanäle unterstützen die Kundenorientierung?', 3, '[{"text": "E-Mail", "correct": true, "because": "Schriftlich und nachvollziehbar"}, {"text": "Telefon", "correct": true, "because": "Direkt und persönlich"}, {"text": "Ticketsysteme", "correct": true, "because": "Strukturiert und effizient"}, {"text": "Netzwerkprotokolle", "correct": false, "because": "Technisch, nicht kundenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Kundenorientierung in der IT?', 3, '[{"text": "Höhere Kundenzufriedenheit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Langfristige Kundenbindung", "correct": true, "because": "Schafft Vertrauen"}, {"text": "Bessere Reputation", "correct": true, "because": "Positives Image"}, {"text": "Geringere technische Qualität", "correct": false, "because": "Nicht relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kundenorientierung erfordert Verständnis für Kundenanliegen. b) Technische Details sind immer wichtiger als Kundensprache.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verständnis ja, Details sekundär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Proaktive Kommunikation fördert die Kundenorientierung. b) Kundenfeedback ist für die Orientierung irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Proaktiv ja, Feedback wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Empathie in der Kommunikation steigert die Kundenorientierung. b) Kunden erwarten keine schnellen Antworten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Empathie ja, Schnelligkeit gewünscht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kundenorientierung kann die Projektqualität verbessern. b) Kundenwünsche sollten immer ignoriert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, Ignorieren negativ"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Klare Kommunikation unterstützt die Kundenorientierung. b) Kundenorientierung ist nur bei großen Projekten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klarheit ja, Relevanz allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

